SELECT CASE WHEN EXISTS (
    SELECT 1 FROM bond
    WHERE bond_type = '=' AND molecule_id IN (
        SELECT molecule_id FROM bond GROUP BY molecule_id HAVING COUNT(*) = (
            SELECT MAX(count_bonds) FROM (
                SELECT COUNT(*) AS count_bonds FROM bond WHERE bond_type = '=' GROUP BY molecule_id
            )
        )
    )
) THEN 'Yes' ELSE 'No' END AS Is_Carcinogenic	----- bird -----	toxicology

